// UsdGeom.Mesh schema — typed attribute extraction.
// Returns plain TypeScript types (Float32Array, Int32Array).
// No renderer dependency.
//
// Attribute names follow the UsdGeom domain spec.
// USDC returns Vec3f[] as number[][], int[] as number[], token as string.

export const MESH_ATTR = {
  points: 'points',
  normals: 'normals',
  primvarsNormals: 'primvars:normals',
  faceVertexCounts: 'faceVertexCounts',
  faceVertexIndices: 'faceVertexIndices',
  uvs: 'primvars:st',
  uvsIndices: 'primvars:st:indices',
  uvsInterpolation: 'primvars:st:interpolation',
  extent: 'extent',
  // subdivision tags (UsdGeomMesh)
  subdivisionScheme: 'subdivisionScheme',
  interpolateBoundary: 'interpolateBoundary',
  faceVaryingLinearInterpolation: 'faceVaryingLinearInterpolation',
  triangleSubdivisionRule: 'triangleSubdivisionRule',
  creaseIndices: 'creaseIndices',
  creaseLengths: 'creaseLengths',
  creaseSharpnesses: 'creaseSharpnesses',
  cornerIndices: 'cornerIndices',
  cornerSharpnesses: 'cornerSharpnesses',
  holeIndices: 'holeIndices',
} as const

// Primvar interpolation modes as defined by UsdGeom.
export type Interpolation = 'constant' | 'uniform' | 'varying' | 'vertex' | 'faceVarying'

// Subdivision-tag token sets (UsdGeomMesh schema), with upstream defaults noted.
export type SubdivisionScheme = 'catmullClark' | 'none' | 'loop' | 'bilinear'
export type InterpolateBoundary = 'none' | 'edgeOnly' | 'edgeAndCorner'
export type FaceVaryingLinearInterpolation =
  | 'none' | 'cornersOnly' | 'cornersPlus1' | 'cornersPlus2' | 'boundaries' | 'all'
export type TriangleSubdivisionRule = 'catmullClark' | 'smooth'

// Schema fallbacks — mirror pxr/usd/usdGeom/schema.usda exactly.
export const SUBDIV_DEFAULTS = {
  subdivisionScheme: 'catmullClark',
  interpolateBoundary: 'edgeAndCorner',
  faceVaryingLinearInterpolation: 'cornersPlus1',
  triangleSubdivisionRule: 'catmullClark',
} as const

export interface UVPrimvar {
  data: Float32Array       // u,v pairs flat: [u0,v0, u1,v1, ...]
  indices: Int32Array | null
  interpolation: Interpolation
}

